const fs: any[][] = [];
for (let row=2;row<=35;row++) fs.push([`=IFERROR(INDEX($H$2:$H$35,MATCH(1,INDEX(($I$2:$I$35=B${row})*($J$2:$J$35=C${row}),0),0)),"")`]);
const r = wb.getRange('Sheet1!A2:A35');
r.setValues(fs);
r.getStyle().setFill('#FCD5B4');
const v = wb.getWorksheet('Sheet1').getView();
v.setShowRowGridlines(false); v.setShowColumnGridlines(false);
log(wb.getRange('A1:C35'));
log(wb.getRange('A2').getCell());
log(wb.getRange('A35').getCell());
log(wb.getWorksheet('Sheet1').getRegions('fill'));
log(v.isShowRowGridlines(), v.isShowColumnGridlines());
log('errors', wb.getRange('A2:A35').getCounts());
const c = await wb.evaluate('=SUMPRODUCT(COUNTIFS($I$2:$I$35,B2:B35,$J$2:$J$35,C2:C35))');
log('matches', c);

